sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    console.debug(">>>Employee - Selected Item:\n", event.name);
    // const produce = imports["x_1813832_1.immer"]().produce;

    const item = event.context.item.value;
    const idx = event.context.item.index;
    // ↓detailのレコードをコピーして取得
    // json形式のデータを取得
    // console.warn(records.);





    item.employee.value = event.payload.value;
    // ↓でユーザーID取得できる。
    item.employee.displayValue = event.payload.item.label;
    const test = event.payload.item.label;
    item.employee.selected = true;
    // item.employee.item = event.payload.item;


    const subLabels = event.payload.item.sublabel.split("|");
    // console.warn(event.payload.item.label);
    const employee_number = subLabels[0];
    const employee_name = subLabels[1];
    const employee_title = subLabels[2];
    const department_name = subLabels[3];

    // 従業員番号
    item.employee_number.value = subLabels[0];
    item.employee_number.displayValue = subLabels[0];
    // 氏名
    item.employee_name.value = subLabels[1];
    item.employee_name.displayValue = subLabels[1];

    item.old_title.value = employee_title;
    item.old_title.displayValue = employee_title;

    item.old_dept.value = department_name;
    item.old_dept.displayValue = department_name;

    console.debug(">>>Employee - Selected Item", "CSPデータをクリア");
    // api.setState("listGaudi", []);
    // api.setState("queryGaudi", "");
    // api.setState("inputValue", "");

    api.data.look_up_user.refresh();

    // let testArray = [];
    // console.warn(testArray);

    // for (let i = 0; i < records.length; i++) {
    //     console.warn(records[i][0]);
    // }
    // for (let i = 0; i < records.length; i++) {
    //     console.warn[i];
    //     testArray[i].push(records[i].employee.displayValue);
    // }

    // let records = structuredClone(api.state.records);
    // console.warn(records.length);
    // let testArray = [];
    let userId = event.payload.item.label;
    console.warn(userId);
    api.setState("userId", userId);
    api.setState("num", idx);
    // api.data.look_up_affiliation.refresh();

    const dept = api.data.look_up_affiliation.results();
    console.warn(dept);
    item.old_dept.value = dept;
    item.old_dept.displayValue = dept;

    const grade = api.data.look_up_affiliation.results();
    console.warn("gradeの結果");
    console.warn(grade);
    item.old_title.value = grade;
    item.old_title.displayValue = grade;


    // for (let i = 0; i < records.length; i++) {
    //     // testArray.push(records[i].employee.displayValue);
    //     console.warn(i);
    //     userId = records[i].employee.displayValue;
    //     console.warn(userId);
    //     api.setState("userId", userId);
    //     api.setState("num", i);
    //     api.data.look_up_affiliation.execute();
    // }


    // console.warn[testArray];

    // console.warn(testArray);
    // api.setState("userId", testArray);
    // console.warn("userId");
